// Factory
function createUser(type) {
  const users = {
    admin: { role: "admin", permissions: ["read", "write", "delete"] },
    guest: { role: "guest", permissions: ["read"] }
  };
  return { ...users[type], createdAt: new Date() };
}
let admin = createUser("admin");

// Singleton
class Database {
  static #instance = null;
  static getInstance() {
    if (!Database.#instance) {
      Database.#instance = new Database();
    }
    return Database.#instance;
  }
  query(sql) { console.log("Executing:", sql); }
}
let db1 = Database.getInstance();
let db2 = Database.getInstance();
console.log(db1 === db2);  // true

// Builder
class RequestBuilder {
  constructor() { this.options = {}; }
  url(u) { this.options.url = u; return this; }
  method(m) { this.options.method = m; return this; }
  header(k, v) { this.options.headers = { ...this.options.headers, [k]: v }; return this; }
  build() { return { ...this.options }; }
}
let req = new RequestBuilder()
  .url("/api/users")
  .method("GET")
  .header("Accept", "application/json")
  .build();

// Adapter: convert old API to new interface
class OldAPI {
  getRequest(url) { return fetch(url); }
}

class APIAdapter {
  constructor(oldApi) { this.api = oldApi; }
  async get(url) {
    let response = await this.api.getRequest(url);
    return { data: await response.json(), status: response.status };
  }
}

