let proxy = new Proxy({ data: 42 }, handler);

// Decorator: add timing to any function
function withTiming(fn) {
  return function(...args) {
    console.time(fn.name);
    let result = fn(...args);
    console.timeEnd(fn.name);
    return result;
  };
}
let fastSum = withTiming((a, b) => a + b);
fastSum(1, 2);  // logs timing info

// Observer/PubSub
class EventBus {
  constructor() { this.listeners = {}; }
  on(event, fn) {
    (this.listeners[event] = this.listeners[event] || []).push(fn);
  }
  emit(event, data) {
    (this.listeners[event] || []).forEach(fn => fn(data));
  }
}
let bus = new EventBus();
bus.on("user:login", (user) => console.log("Welcome", user.name));
bus.emit("user:login", { name: "Alex" });

// Strategy
function sort(arr, strategy) {
  return [...arr].sort(strategy);
}
let byNumber = (a, b) => a - b;
let byLength = (a, b) => a.length - b.length;
console.log(sort([3, 1, 2], byNumber));     // [1, 2, 3]
console.log(sort(["b", "aa", "c"], byLength));  // ["b", "c", "aa"]

// Command
class Calculator {
  constructor() { this.history = []; this.current = 0; }
  execute(cmd) { this.history.push(cmd); cmd.execute(this); }
  undo() { this.history.pop()?.undo(this); }
}
class AddCommand {
  constructor(value) { this.value = value; }
  execute(calc) { calc.current += this.value; }
  undo(calc) { calc.current -= this.value; }
}
let calc = new Calculator();
calc.execute(new AddCommand(5));
console.log(calc.current);  // 5
calc.undo();
console.log(calc.current);  // 0

